import{_ as d,o as r,c as o,a4 as n}from"./chunks/framework.BabNWGMA.js";const b=JSON.parse('{"title":"🎯 学习计划","description":"","frontmatter":{},"headers":[],"relativePath":"plan.md","filePath":"plan.md","lastUpdated":1789273189000}'),a={name:"plan.md"};function s(e,t,l,i,g,h){return r(),o("div",null,[...t[0]||(t[0]=[n('<h1 id="🎯-学习计划" tabindex="-1">🎯 学习计划 <a class="header-anchor" href="#🎯-学习计划" aria-label="Permalink to &quot;🎯 学习计划&quot;">​</a></h1><blockquote><p>目标:华中科技大学考研(数学一 + 机械原理专业课 + 英语一)+ 炼油化工设备技术员层次 本文件是学习系统执行的依据,每日任务按此推进。2026-08-08 用户确认&quot;按计划进行&quot;。 ⏰ <strong>2026-08-16 用户设定:所有学习目标提前 30 天完成</strong>(考试 12-26,学习主体 11-25 前结束,11-26~12-25 为 30 天自由复习缓冲期)</p></blockquote><h2 id="一、总体框架-三阶段-缓冲期" tabindex="-1">一、总体框架(三阶段 + 缓冲期) <a class="header-anchor" href="#一、总体框架-三阶段-缓冲期" aria-label="Permalink to &quot;一、总体框架(三阶段 + 缓冲期)&quot;">​</a></h2><h3 id="阶段一-·-基础扫盲-2026-08-08-09-15-约-5-5-周" tabindex="-1">阶段一 · 基础扫盲(2026-08-08 ~ 09-15,约 5.5 周) <a class="header-anchor" href="#阶段一-·-基础扫盲-2026-08-08-09-15-约-5-5-周" aria-label="Permalink to &quot;阶段一 · 基础扫盲(2026-08-08 ~ 09-15,约 5.5 周)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>科目</th><th>内容</th><th>节奏</th></tr></thead><tbody><tr><td>高等数学</td><td>极限→导数→一元积分→微分方程→多元微分→多元积分(二重)→级数(缺口)</td><td>每周 3 个专题</td></tr><tr><td>线性代数</td><td>行列式→矩阵→向量→线性方程组→特征值与特征向量→二次型</td><td>每周 2 个专题</td></tr><tr><td>概率论</td><td>随机事件与概率→随机变量分布→多维随机变量→数字特征→大数定律→数理统计→参数估计</td><td>每周 1 个专题</td></tr><tr><td>机械原理</td><td>机构分析→运动学→力分析→齿轮/轮系→平衡→调速</td><td>每周 2 个专题</td></tr><tr><td>炼油化工设备</td><td>泵/压缩机/风机/离心机 原理+结构+选型+故障</td><td>每周 1-2 个专题</td></tr><tr><td>英语</td><td>每日新词按模式配额(light15/standard30/intensive45, 唯一来源=study_manager.MODES.new_vocab) + 1 长难句;词汇走独立逐词库 vocab/</td><td>每天</td></tr></tbody></table><h3 id="阶段二-·-强化真题-2026-09-16-10-19-约-5-周" tabindex="-1">阶段二 · 强化真题(2026-09-16 ~ 10-19,约 5 周) <a class="header-anchor" href="#阶段二-·-强化真题-2026-09-16-10-19-约-5-周" aria-label="Permalink to &quot;阶段二 · 强化真题(2026-09-16 ~ 10-19,约 5 周)&quot;">​</a></h3><ul><li>高数/机械:华科真题题型专项(计算题、证明题)</li><li>设备:结合催化裂化装置现场案例</li><li>英语:阅读理解真题精做</li></ul><h3 id="阶段三-·-冲刺模拟-2026-10-20-11-25-约-5-周" tabindex="-1">阶段三 · 冲刺模拟(2026-10-20 ~ 11-25,约 5 周) <a class="header-anchor" href="#阶段三-·-冲刺模拟-2026-10-20-11-25-约-5-周" aria-label="Permalink to &quot;阶段三 · 冲刺模拟(2026-10-20 ~ 11-25,约 5 周)&quot;">​</a></h3><ul><li>全真模拟 + 错题总复习</li><li>高频考点背诵 + 英语作文模板</li></ul><h3 id="🕐-缓冲期-2026-11-26-12-25-30-天" tabindex="-1">🕐 缓冲期(2026-11-26 ~ 12-25,30 天) <a class="header-anchor" href="#🕐-缓冲期-2026-11-26-12-25-30-天" aria-label="Permalink to &quot;🕐 缓冲期(2026-11-26 ~ 12-25,30 天)&quot;">​</a></h3><ul><li>自由复习:错题本清零、薄弱知识点最后扫尾、考前心态调整</li><li>每周保持轻量复习(light 模式)防止遗忘,不再推送新内容</li></ul><h2 id="二、执行机制-系统自动" tabindex="-1">二、执行机制(系统自动) <a class="header-anchor" href="#二、执行机制-系统自动" aria-label="Permalink to &quot;二、执行机制(系统自动)&quot;">​</a></h2><ul><li>每日动态模式(时间口径唯一来源=study_manager.py MODES):light(约25min)/ standard(约45min)/ intensive(约75min)/ regression(约30min)</li><li>科目轮换(<strong>建议1 2026-09-11 更新·数学一拆三科</strong>): 周一 高数+机械 / 周二 线代+英语 / 周三 高数+机械 / 周四 线代+概率 / 周五 高数+机械 / 周六 机械+设备 / 周日 总结+错题复习 每周 12 时段 = 高数3 · 线代2 · 概率1 · 机械4 · 英语1 · 设备1(方案C 数学加重)</li><li>定时任务:06:00 晨间询问 → 06:30 知识点推送 → <strong>07:30 / 13:30 / 19:00 三次小测</strong>(上海时间)→ 20:00 复盘 → 周日周报</li><li>错题间隔复习:1/3/7/14 天自动</li></ul><h2 id="三、优先级策略-用户确认" tabindex="-1">三、优先级策略(用户确认) <a class="header-anchor" href="#三、优先级策略-用户确认" aria-label="Permalink to &quot;三、优先级策略(用户确认)&quot;">​</a></h2><ol><li><strong>数学一三科最优先</strong>(占考研 150 分,是最大缺口):高数 3 时段 + 线代 2 + 概率 1 = 每周 6 时段 <ul><li>建议周六/周日至少一天切 intensive 专攻高数专题</li></ul></li><li><strong>英语词汇</strong>:配额以 MODES.new_vocab 为准(15/30/45),不再写「每日 8 词」; ⚠️ 词库目前仅 45 个种子词(已按每日 15 词分摊到期),距考研英语一 5500 词缺口大 —— 扩词需真实词表(单词书/真题词表),由用户提供后再导入</li><li><strong>设备科保持</strong>:掌握度 50% 领先,维持节奏即可</li></ol><h2 id="四、阶段目标" tabindex="-1">四、阶段目标 <a class="header-anchor" href="#四、阶段目标" aria-label="Permalink to &quot;四、阶段目标&quot;">​</a></h2><h3 id="_09-15-阶段一末·提前30天-——验收口径已改-建议13" tabindex="-1">09-15(阶段一末·提前30天)——<strong>验收口径已改(建议1③)</strong> <a class="header-anchor" href="#_09-15-阶段一末·提前30天-——验收口径已改-建议13" aria-label="Permalink to &quot;09-15(阶段一末·提前30天)——**验收口径已改(建议1③)**&quot;">​</a></h3><p>数学一三科(高数/线代/概率)<strong>不以掌握度均值验收</strong>,改用 <strong>范围扫盲完成度</strong>:</p><blockquote><p><strong>范围扫盲完成度 = 大纲章节中「知识库至少 1 条」的章节数 ÷ 章节总数</strong></p></blockquote><ul><li>数学一目标:高数 11 章 ≥ 9 章有覆盖;线代 6 章 ≥ 4 章;概率 8 块 ≥ 4 块 (⚠️ 章节划分按通用大纲口径,非官方 2027 逐条;复习中期再按真题校准)</li><li>理由:零覆盖科目即使入库 1 条也会把&quot;掌握度均值&quot;拉到默认 50%,均值口径会掩盖&quot;根本没开始&quot;的事实。</li></ul><h3 id="掌握度目标-其余科目-延后一阶段" tabindex="-1">掌握度目标(其余科目,延后一阶段) <a class="header-anchor" href="#掌握度目标-其余科目-延后一阶段" aria-label="Permalink to &quot;掌握度目标(其余科目,延后一阶段)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>时间点</th><th>高数</th><th>机械原理</th><th>英语</th><th>设备</th></tr></thead><tbody><tr><td>10-19(阶段二末·提前30天)</td><td>65%</td><td>65%</td><td>70%</td><td>75%</td></tr><tr><td>11-25(冲刺末·提前30天)</td><td>85%+</td><td>85%+</td><td>85%+</td><td>85%+</td></tr></tbody></table><h2 id="四点五、数学一·范围缺口清单-建议12-产出-2026-09-11-只读盘点" tabindex="-1">四点五、数学一·范围缺口清单(建议1② 产出,2026-09-11 只读盘点) <a class="header-anchor" href="#四点五、数学一·范围缺口清单-建议12-产出-2026-09-11-只读盘点" aria-label="Permalink to &quot;四点五、数学一·范围缺口清单(建议1② 产出,2026-09-11 只读盘点)&quot;">​</a></h2><p>数据源:<code>knowledge/高等数学.json</code>(28 条)+ 是否有 <code>线性代数.json</code>/<code>概率论.json</code>。</p><p><strong>❌ 高数零覆盖(5 章,必推)</strong></p><ol><li>向量代数与空间解析几何</li><li>三重积分(含柱面坐标/球面坐标)</li><li>曲线积分(第一类/第二类)</li><li>曲面积分(第一类/第二类)+ 格林公式 / 高斯公式 / 斯托克斯公式</li><li>无穷级数(数项级数审敛、幂级数、傅里叶级数)</li></ol><p><strong>⚠️ 高数已覆盖但偏薄(需补深度)</strong></p><ul><li>多元函数微分学:仅&quot;偏导数/全微分&quot;2 条,<strong>缺</strong> 极值、拉格朗日乘数法、几何应用</li><li>一元微分学应用:缺中值定理(罗尔/拉格朗日/柯西)、单调性与极值、曲率</li><li>二重积分:6 条(相对充分,注意与三重积分衔接)</li></ul><p><strong>❌ 线性代数 6 章全部零覆盖(必推)</strong> 行列式 / 矩阵 / 向量 / 线性方程组 / 特征值与特征向量 / 二次型</p><p><strong>❌ 概率论 8 块全部零覆盖(必推)</strong> 随机事件与概率 / 一维随机变量及其分布 / 多维随机变量 / 随机变量数字特征 / 大数定律与中心极限定理 / 数理统计基本概念 / 参数估计 / 假设检验</p><p><strong>排期建议(106 天,含冲刺期)</strong>: 高数缺口 5 章 + 补薄 3 处 → 09-11 起每周 3 个专题,约 6~7 周(10 月底前)覆盖; 线代 6 章 × 每周 2 专题 ≈ 3 周;概率 8 块 × 每周 1 专题 ≈ 8 周(与线代并行,11 月底前)。 ⚠️ 与&quot;11-25 主体结束、提前 30 天&quot;的原目标相比,数学一<strong>明显偏紧</strong>,若 10 月底仍未覆盖级数/线代,需考虑占用周日或上调 intensive 频率。</p><h2 id="当前周计划-2026-10-05-10-11-动态调整版·由-2026-10-04-周报生成" tabindex="-1">当前周计划(2026-10-05 ~ 10-11,动态调整版·由 2026-10-04 周报生成) <a class="header-anchor" href="#当前周计划-2026-10-05-10-11-动态调整版·由-2026-10-04-周报生成" aria-label="Permalink to &quot;当前周计划(2026-10-05 ~ 10-11,动态调整版·由 2026-10-04 周报生成)&quot;">​</a></h2><p>数据源:<code>weekly_archive.py --summary</code>(2026-10-04 上海,距考研 <strong>83 天</strong>,强化阶段)</p><h3 id="⚠️-现状三句话-最重要" tabindex="-1">⚠️ 现状三句话(最重要) <a class="header-anchor" href="#⚠️-现状三句话-最重要" aria-label="Permalink to &quot;⚠️ 现状三句话(最重要)&quot;">​</a></h3><ol><li><strong>熔断第 12 天</strong>:最后学习日 <strong>2026-09-21</strong>,连续 <strong>12 天</strong>零作答;本周(09-28~10-04)学习天数 <strong>0/7</strong>,累计 <strong>18 天(无新增)</strong>。 系统每天只保留 <strong>06:45「起床唤醒」一条</strong>消息,其余推送静默。 <strong>恢复门槛 = 回一个字/答一题</strong> → 立即跑 <code>study_manager.py reengage</code>(只写标记不记账) → 首日按「回归日」跑(全天 4 题 = 最旧 2 条到期 + 最早 2 条错题,午场不出题,lesson 不推新专题),连续正常作答 2 天自动回升 standard。</li><li><strong>欠账冻结但没消失</strong>:到期复习 <strong>102 条</strong>(上周 102)、错题未解决 <strong>26 条</strong>(机械 11 / 英语 8 / 设备 5 / 高数 2)、 卡点 <strong>13 条 = 4 个考点族,全部 ⛳超期</strong>(by which 滞留 57 天 / 气蚀气缚 41 天 / 定轴轮系 40 天 / 刚性转子平衡 26 天)。 本周新错 0、转 solved 0 —— 这是「<strong>没作答</strong>」,不是「变好了」。</li><li><strong>数学一结构性缺口仍未动</strong>:线性代数 <strong>0 条</strong>、概率论 <strong>0 条</strong>(报表按占位 50% 计,不代表已学)。 国庆(10-01~10-07)预设的 intensive 冲刺未发生;阶段二(09-16~10-19 强化真题)已过半,10-19 末 65% 的分阶段目标<strong>已不可达</strong>,本周策略改为「先把作答线接回来」。</li></ol><h3 id="上周数据基线-09-28-10-04" tabindex="-1">上周数据基线(09-28 ~ 10-04) <a class="header-anchor" href="#上周数据基线-09-28-10-04" aria-label="Permalink to &quot;上周数据基线(09-28 ~ 10-04)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>科目</th><th>掌握度</th><th>知识点数</th><th>最近学习</th><th>未解决错题</th><th>卡点</th></tr></thead><tbody><tr><td>高等数学</td><td>52%</td><td>15</td><td>09-21</td><td>2</td><td>0</td></tr><tr><td>线性代数</td><td>50%(占位,0 条)</td><td>0</td><td>—</td><td>0</td><td>0</td></tr><tr><td>概率论</td><td>50%(占位,0 条)</td><td>0</td><td>—</td><td>0</td><td>0</td></tr><tr><td>机械原理</td><td>53%</td><td>42</td><td>09-20</td><td>11</td><td>5</td></tr><tr><td>英语</td><td>51%</td><td>22</td><td>09-20</td><td>8</td><td>5</td></tr><tr><td>炼油化工设备</td><td>60%</td><td>18</td><td>09-08</td><td>5</td><td>3</td></tr></tbody></table><ul><li>知识库合计 <strong>97 条</strong>;四科(高数/机械/英语/设备)掌握度均值 <strong>54.0%</strong>,距 11-25 末 85% 目标差 <strong>33 / 32 / 34 / 25</strong> 个百分点。</li><li>错题本 Top3:机械「局部自由度陷阱(凸轮滚子)」/ 英语「by which + not only...but also + 非限制性定语从句」/ 高数「极坐标换元 √(x²+y²) 二重积分」。</li><li>词汇:知识库去重 <strong>16 词</strong>,核心词 1800 覆盖 <strong>≈0.89%</strong>(扩词需用户提供真实词表)。</li><li>出题重复率:<strong>本周无批改记录</strong>(近 7 天 0 题入库)→ 无法计算;恢复作答后重新取样,期间仍执行「同考点 ≥2 次即换主题」。</li><li>脚本已落可执行参数:错题必测 <strong>4 条/天</strong>(回归日自动 cap 2);弱科额外配额 <strong>1 条</strong>(最弱=线性代数,库内 0 条 → 顺延给「库内有条目且掌握最低」的科目)。</li></ul><h3 id="下周动态调整清单" tabindex="-1">下周动态调整清单 <a class="header-anchor" href="#下周动态调整清单" aria-label="Permalink to &quot;下周动态调整清单&quot;">​</a></h3><p><strong>📈 1. 科目优先级(本周唯一核心 KPI = 破熔断)</strong></p><ol><li><strong>恢复作答(最高优先级,压过一切学习内容)</strong>:任一天回一个字/答一题 → <code>reengage</code> → 当日按回归日(4 题)跑。本周<strong>不追题量</strong>,只追「连续 2 天有作答」。</li><li><strong>机械原理(53%,11 错题 + 5 卡点)→ 第一优先级</strong>:错题闭环 + 卡点族专治;每周 2 专题(轮系 → 平衡)。</li><li><strong>高等数学(52%)→ 第二优先级</strong>:到期消费为主 + 每周 1 个新专题(<strong>无穷级数</strong>首推缺口);多元微分补薄(极值、拉格朗日乘数法)。</li><li><strong>英语(51%,词汇覆盖 &lt;1%)→ 每天固定 1 题词汇 + 1 长难句</strong>;⚠️ 现库仅 45 词,配额不可持续 —— <strong>需用户提供真实词表</strong>。</li><li><strong>线性代数(0 条)/ 概率论(0 条)→ 零覆盖补位</strong>:线代先推「行列式」并<strong>作答确认</strong>后再进「矩阵」;概率周四<strong>必推</strong>首档「随机事件与概率」;各每周 1 档,不铺开。</li><li><strong>炼油化工设备(60%,唯一达标项)→ 只维持</strong>:到期复习 + 气蚀/气缚超期卡点,不加量。</li></ol><p><strong>🎯 2. 薄弱知识点专项(掌握 &lt;40%,本周至少重测 1 次,优先排到期)</strong></p><table tabindex="0"><thead><tr><th>科目</th><th>知识点</th><th>处方</th></tr></thead><tbody><tr><td>英语</td><td>长难句:by which 定语从句(30%)⛳超期</td><td>换讲法:拆最小前置(介词+which 常是 where/when 的替身) → 让用户用自己的话复述</td></tr><tr><td>英语</td><td>distinguish between A and B(30%)</td><td>固定搭配换语境重测 1 次</td></tr><tr><td>高数</td><td>复合函数求导(链式法则)(30%)</td><td>概念澄清 + 换数据重测</td></tr><tr><td>高数</td><td>极坐标换元 √(x²+y²) 二重积分(30%)</td><td>错题 Top3 → 重讲极坐标定限 + 换题重测</td></tr><tr><td>机械</td><td>局部自由度陷阱(凸轮滚子)</td><td>错题 Top1 → 概念澄清(滚子不计)+ 换数据重测</td></tr><tr><td>机械</td><td>定轴轮系传动比 ⛳超期</td><td>换讲法:先拆最小前置(定轴=各轴独立)再复述</td></tr><tr><td>机械</td><td>刚性转子平衡·质径积法 ⛳超期</td><td>配图重讲矢量合成 + 重测</td></tr><tr><td>设备</td><td>离心泵气蚀/气缚辨析 ⛳超期</td><td>对比讲法:气缚=没灌泵;气蚀=局部压力低于汽化压</td></tr><tr><td>线代/概率</td><td>行列式的定义与性质 / 随机事件与概率</td><td>首档知识点 → <strong>验证题作答才记入</strong>(未答不算学过)</td></tr></tbody></table><blockquote><p>上表以本周 <code>--summary</code> 的错题 Top3 + 4 个超期卡点族 + 未解决错题分布为准;其余 &lt;40% 条目以当天 <code>knowledge_base.py due</code> 输出为准。</p></blockquote><p><strong>🚧 3. 卡点处置(4 族全超期,滞留 ≥14 天 → 走升级处方)</strong> ①当天固定出 1 题(计入全天配额)②精讲改「<strong>换讲法</strong>」:拆最小前置概念 + 让用户复述 ③连出两次仍错 → 推送里点名请用户单独提问(人工介入)。 一族只占 1 个名额;晚场见卡点<strong>不出数字变式</strong>,出 ≤5 行概念精讲 + 1 道口述思路题。</p><p><strong>📋 4. 错题重测(脚本参数:每天 4 条;回归日自动 cap 2 条)</strong> 清题顺序:<strong>机械 11 条</strong>(局部自由度陷阱 → 速度瞬心法 → 定轴轮系 → 静平衡配重 → 基圆 db)→ <strong>英语 8 条</strong>(by which 长难句 → 固定搭配)→ <strong>设备 5 条</strong>(气蚀/气缚 → 主风机振动)→ <strong>高数 2 条</strong>(极坐标二重积分)。每天 1 题是底线,回归日不超 2 题。</p><p><strong>🔇 5. 强项降频</strong>:本轮到期采样(前 40 条)内最高掌握度 70%,<strong>未命中 ≥80% 条目</strong> → 本轮不启用降频,恢复作答后重评。</p><p><strong>📌 6. 补课</strong>:09-28~10-04 连续 <strong>7 天</strong>无记录 → 按补课规则<strong>只补最近一天要点</strong>(标注「📌 补课」),连续缺勤不堆内容;答完验证题才记入学习数据(补课不自动 mark-day)。</p><p><strong>📅 7. 到期复习处方(102 条积压;每天 2~3 条核心,按当日轮换科目优先,清不完滚动)</strong></p><table tabindex="0"><thead><tr><th>日</th><th>轮换科目</th><th>到期复习(核心 2~3 条)</th><th>错题/卡点</th></tr></thead><tbody><tr><td>周一 10-05</td><td>高数 + 机械</td><td>高数:函数的连续性与间断点(70%)、极限的计算(60%);机械:局部自由度陷阱(族)</td><td>错题 2 条(机械)</td></tr><tr><td>周二 10-06</td><td>线代 + 英语</td><td>线代:行列式的定义与基本性质;英语:by which 长难句(30%)、distinguish between A and B(30%)</td><td>⛳by which 卡点固定 1 题</td></tr><tr><td>周三 10-07</td><td>高数 + 机械</td><td>高数:极坐标换元二重积分(30%)、链式法则(30%);机械:定轴轮系传动比</td><td>⛳定轴轮系固定 1 题</td></tr><tr><td>周四 10-08</td><td>线代 + 概率</td><td>线代:行列式的计算(化三角形法/展开定理);概率:随机事件与样本空间(<strong>首档验证题</strong>)</td><td>概率首档必作答</td></tr><tr><td>周五 10-09</td><td>高数 + 机械</td><td>高数:分部积分法、导数的定义与几何意义;机械:速度瞬心法的应用</td><td>错题 2 条</td></tr><tr><td>周六 10-10</td><td>机械 + 设备</td><td>机械:刚性转子平衡(质径积);设备:离心泵气蚀/气缚辨析</td><td>⛳两族各固定 1 题</td></tr><tr><td>周日 10-11</td><td>周总结 + 错题总复习</td><td>未清到期滚动 + 本周错题复盘;线代/概率各抽 1 条</td><td>未清项滚动下周</td></tr></tbody></table><blockquote><p>🎌 国庆假期(至 10-07):若用户回复「放假有空」→ 当日切 intensive(3 知识点/15 题),优先补线代/概率零覆盖与机械卡点族;否则维持 standard,不主动加量。</p></blockquote><p><strong>✅ 8. 可衡量周目标</strong>:<strong>破熔断 = 学习天数 ≥2/7</strong>(唯一硬指标);验证题作答 ≥8 题;错题未解决 26 → ≤22;到期消化 ≥10 条;卡点解除 ≥1 族(by which 或定轴轮系优先);线代 ≥1 条作答确认(行列式);概率 ≥1 条首档;周末掌握度:高数 ≥53%、机械 ≥54%、英语 ≥52%、设备 ≥60%。</p>',52)])])}const u=d(a,[["render",s]]);export{b as __pageData,u as default};
